:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --button-bg: #1f4068;
  --button-hover: #2a5a8a;
  --button-active: #e94560;
  --door-open: #4caf50;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  border: 2px solid var(--primary);
}

h1 {
  font-size: 1.75rem;
  text-align: center;
  margin-bottom: 24px;
  color: var(--accent);
  letter-spacing: 0.05em;
}

.elevator-display {
  background: var(--primary);
  border-radius: 16px;
  padding: 20px;
  margin-bottom: 24px;
  display: flex;
  justify-content: space-around;
  align-items: center;
  gap: 12px;
  border: 2px solid var(--accent);
}

.floor-indicator {
  font-size: 3rem;
  font-weight: bold;
  color: var(--accent);
  min-width: 2ch;
  text-align: center;
  line-height: 1;
}

.direction-indicator {
  font-size: 1.5rem;
  color: var(--text);
  opacity: 0.8;
}

.door-indicator {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text);
  opacity: 0.6;
}

.door-indicator.open {
  color: var(--door-open);
  opacity: 1;
}

.floor-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 24px;
}

.floor-btn {
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: 600;
  padding: 16px 8px;
  border: 2px solid var(--primary);
  border-radius: 12px;
  background: var(--button-bg);
  color: var(--text);
  cursor: pointer;
  transition: all 0.15s ease;
  min-height: 56px;
}

.floor-btn:hover {
  background: var(--button-hover);
  border-color: var(--accent);
}

.floor-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.floor-btn:active {
  transform: scale(0.95);
  background: var(--button-active);
}

.floor-btn.queued {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--bg);
}

.floor-btn.current {
  box-shadow: 0 0 0 3px var(--door-open);
}

.hint {
  text-align: center;
  font-size: 0.875rem;
  opacity: 0.6;
  line-height: 1.5;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .floor-indicator {
    font-size: 2.5rem;
  }
  .floor-buttons {
    gap: 8px;
  }
  .floor-btn {
    padding: 12px 4px;
    font-size: 1.1rem;
  }
}

[hidden] {
  display: none !important;
}

(function() {
  'use strict';

  const FLOORS = 6;
  const MOVE_INTERVAL = 1000; // 1 second per floor
  const DOOR_OPEN_DURATION = 1500; // 1.5 seconds

  // State
  let currentFloor = 1;
  let direction = 0; // -1 down, 0 idle, 1 up
  let queuedFloors = new Set();
  let doorsOpen = false;
  let moving = false;
  let moveTimer = null;
  let doorTimer = null;

  // DOM elements
  const floorDisplay = document.getElementById('floorDisplay');
  const directionDisplay = document.getElementById('directionDisplay');
  const doorDisplay = document.getElementById('doorDisplay');
  const floorButtonsContainer = document.getElementById('floorButtons');

  // Create floor buttons
  const buttons = [];
  for (let f = 1; f <= FLOORS; f++) {
    const btn = document.createElement('button');
    btn.className = 'floor-btn';
    btn.textContent = f;
    btn.setAttribute('aria-label', 'Floor ' + f);
    btn.dataset.floor = f;
    btn.addEventListener('click', () => queueFloor(f));
    floorButtonsContainer.appendChild(btn);
    buttons.push(btn);
  }

  function queueFloor(floor) {
    if (floor === currentFloor && !doorsOpen) {
      // If already at this floor and doors closed, open doors immediately
      openDoors();
      return;
    }
    if (floor === currentFloor && doorsOpen) {
      // Already open, do nothing
      return;
    }
    queuedFloors.add(floor);
    updateButtonStates();
    if (!moving && !doorsOpen) {
      startMoving();
    }
  }

  function startMoving() {
    if (queuedFloors.size === 0) return;
    moving = true;
    direction = 0;
    moveTimer = setInterval(moveStep, MOVE_INTERVAL);
    updateDisplay();
  }

  function moveStep() {
    if (queuedFloors.size === 0) {
      stopMoving();
      return;
    }

    // Determine next target floor
    const targets = Array.from(queuedFloors);
    // Choose nearest floor (simple approach)
    let nextFloor = targets.reduce((nearest, f) => {
      return Math.abs(f - currentFloor) < Math.abs(nearest - currentFloor) ? f : nearest;
    }, targets[0]);

    if (currentFloor === nextFloor) {
      // Arrived
      queuedFloors.delete(nextFloor);
      updateButtonStates();
      stopMoving();
      openDoors();
      return;
    }

    // Move one step toward nextFloor
    if (nextFloor > currentFloor) {
      currentFloor++;
      direction = 1;
    } else {
      currentFloor--;
      direction = -1;
    }

    updateDisplay();

    // Check if we arrived at the target
    if (currentFloor === nextFloor) {
      queuedFloors.delete(nextFloor);
      updateButtonStates();
      stopMoving();
      openDoors();
    }
  }

  function stopMoving() {
    moving = false;
    direction = 0;
    if (moveTimer) {
      clearInterval(moveTimer);
      moveTimer = null;
    }
    updateDisplay();
  }

  function openDoors() {
    doorsOpen = true;
    updateDisplay();
    updateButtonStates();
    if (doorTimer) clearTimeout(doorTimer);
    doorTimer = setTimeout(() => {
      closeDoors();
    }, DOOR_OPEN_DURATION);
  }

  function closeDoors() {
    doorsOpen = false;
    updateDisplay();
    updateButtonStates();
    if (queuedFloors.size > 0) {
      startMoving();
    }
  }

  function updateDisplay() {
    floorDisplay.textContent = currentFloor;
    if (direction === 1) {
      directionDisplay.textContent = '▲';
    } else if (direction === -1) {
      directionDisplay.textContent = '▼';
    } else {
      directionDisplay.textContent = '—';
    }
    doorDisplay.textContent = doorsOpen ? 'Open' : 'Closed';
    doorDisplay.classList.toggle('open', doorsOpen);
  }

  function updateButtonStates() {
    buttons.forEach(btn => {
      const floor = parseInt(btn.dataset.floor, 10);
      btn.classList.toggle('queued', queuedFloors.has(floor));
      btn.classList.toggle('current', floor === currentFloor);
    });
  }

  // Initial display
  updateDisplay();
  updateButtonStates();
})();
